"""FLE-29: in-network mirror of the fleet's named ports (core/routermirror.py)."""

import pytest

from fleet.core import routermirror
from fleet.core.errors import FleetError, RouterMirrorError
from fleet.core.registry import PortProfile, Registry
from fleet.core.runner import RunResult

HEADER = (
    "# Managed by ddev-fleet (FLE-29): do not edit. "
    "Regenerated by deploy / fleet refresh-ports.\n"
)

TS = PortProfile(name="typesense", public=9108, router=8108)
PW = PortProfile(name="playwright", public=9324, router=8323)


def _registry(tmp_path, *, fleet_extra="", ports="", project_extra="    typesense: true\n"):
    path = tmp_path / "fleet.yml"
    path.write_text(
        f"""\
fleet:
  domain: fleet.example.test
{fleet_extra}{ports}
projects:
  demo:
    git: git@example.test:org/demo.git
{project_extra}    templates:
      default: {{}}
""",
        encoding="utf-8",
    )
    return Registry.load(path)


# --- render ---------------------------------------------------------------


def test_render_spike_case():
    assert routermirror.render_static([TS]) == (
        HEADER + 'entryPoints:\n  fleet-mirror-9108:\n    address: ":9108"\n'
    )
    assert routermirror.render_dynamic([TS]) == (
        HEADER + "tcp:\n"
        "  routers:\n"
        "    fleet-mirror-9108:\n"
        "      entryPoints: [fleet-mirror-9108]\n"
        '      rule: "HostSNI(`*`)"\n'
        "      service: fleet-mirror-9108\n"
        "      tls: {}\n"
        "  services:\n"
        "    fleet-mirror-9108:\n"
        "      loadBalancer:\n"
        "        servers:\n"
        '          - address: "127.0.0.1:8108"\n'
    )


def test_render_several_profiles_in_given_order_and_deterministic():
    static = routermirror.render_static([TS, PW])
    dynamic = routermirror.render_dynamic([TS, PW])
    assert static.startswith(HEADER)
    assert static.index("fleet-mirror-9108") < static.index("fleet-mirror-9324")
    assert '          - address: "127.0.0.1:8323"\n' in dynamic
    assert dynamic.startswith(HEADER)
    assert routermirror.render_static([TS, PW]) == static
    assert routermirror.render_dynamic([TS, PW]) == dynamic


def test_rendered_files_are_valid_yaml():
    from ruamel.yaml import YAML

    yaml = YAML(typ="safe")
    static = yaml.load(routermirror.render_static([TS, PW]))
    dynamic = yaml.load(routermirror.render_dynamic([TS, PW]))
    assert static["entryPoints"]["fleet-mirror-9324"]["address"] == ":9324"
    router = dynamic["tcp"]["routers"]["fleet-mirror-9324"]
    assert router["rule"] == "HostSNI(`*`)"
    assert router["tls"] == {}
    servers = dynamic["tcp"]["services"]["fleet-mirror-9324"]["loadBalancer"]["servers"]
    assert servers == [{"address": "127.0.0.1:8323"}]


