# --- converge -------------------------------------------------------------


class ScriptedRunner:
    """Records calls; `docker inspect` answers from `health` (a list consumed in
    order, the last value repeating); everything else succeeds."""

    def __init__(self, health=("healthy",), fail=()):
        self.calls = []
        self._health = list(health)
        self._fail = set(fail)

    def __call__(self, cmd, **kwargs):
        self.calls.append({"cmd": list(cmd), **kwargs})
        key = " ".join(cmd[:2])
        if key in self._fail:
            return RunResult(returncode=1, lines=["boom"])
        if cmd[:2] == ["docker", "inspect"]:
            status = self._health.pop(0) if len(self._health) > 1 else self._health[0]
            return RunResult(returncode=0, lines=[status])
        return RunResult(returncode=0, lines=[])

    def cmds(self):
        return [c["cmd"] for c in self.calls]


class SequencedFetch:
    """Returns successive entrypoint lists (the last one repeats)."""

    def __init__(self, *states):
        self._states = [None if s is None else [{"name": n} for n in s] for s in states]

    def __call__(self, url):
        state = self._states.pop(0) if len(self._states) > 1 else self._states[0]
        if state is None:
            raise OSError("down")
        return state


def _converge(registry, traefik, runner, fetch, tmp_path, *, sync_first=True, **kwargs):
    traefik.mkdir(exist_ok=True)
    if sync_first:
        routermirror.sync(registry, traefik_dir=traefik)
    sleeps = []
    message = routermirror.converge(
        registry,
        instance_dir=tmp_path / "inst",
        traefik_dir=traefik,
        runner=runner,
        fetch=fetch,
        sleep=sleeps.append,
        **kwargs,
    )
    return message, sleeps


def test_converge_noop_when_live_matches(tmp_path):
    runner = ScriptedRunner()
    fetch = SequencedFetch(["http-80", "fleet-mirror-9108"])
    message, _ = _converge(_registry(tmp_path), tmp_path / "t", runner, fetch, tmp_path)
    assert message == ""
    assert runner.calls == []


def test_converge_noop_when_nothing_wanted_and_nothing_live(tmp_path):
    runner = ScriptedRunner()
    registry = _registry(tmp_path, project_extra="")
    message, _ = _converge(registry, tmp_path / "t", runner, SequencedFetch(["http-80"]), tmp_path)
    assert message == ""
    assert runner.calls == []


def test_converge_unreachable_api_does_nothing(tmp_path):
    runner = ScriptedRunner()
    message, _ = _converge(
        _registry(tmp_path), tmp_path / "t", runner, SequencedFetch(None), tmp_path
    )
    assert message == "router API unreachable; port mirror not verified"
    assert runner.calls == []


def test_converge_restarts_router_and_reports_success(tmp_path):
    runner = ScriptedRunner(health=["starting", "healthy"])
    fetch = SequencedFetch(["http-80"], ["http-80", "fleet-mirror-9108"])

    message, sleeps = _converge(_registry(tmp_path), tmp_path / "t", runner, fetch, tmp_path)

    assert message == "restarted ddev-router: port mirror now 9108"
    cmds = runner.cmds()
    assert cmds[0] == ["docker", "restart", "ddev-router"]
    assert cmds[1][:3] == ["docker", "inspect", "-f"] and cmds[1][-1] == "ddev-router"
    assert len(cmds) == 3  # restart + two health polls, no ddev start
    assert sleeps == [2.0]


def test_converge_restarts_to_drop_stale_mirror_entrypoint(tmp_path):
    runner = ScriptedRunner()
    registry = _registry(tmp_path, fleet_extra="  port_mirror: false\n")
    fetch = SequencedFetch(["http-80", "fleet-mirror-9108"], ["http-80"])

    message, _ = _converge(registry, tmp_path / "t", runner, fetch, tmp_path)

    assert message == "restarted ddev-router: port mirror now none"
    assert runner.cmds()[0] == ["docker", "restart", "ddev-router"]


def test_converge_failure_self_repairs_and_raises(tmp_path):
    traefik = tmp_path / "traefik"
    registry = _registry(tmp_path)
    runner = ScriptedRunner(health=["unhealthy"])
    fetch = SequencedFetch(["http-80"])

    with pytest.raises(RouterMirrorError) as excinfo:
        _converge(registry, traefik, runner, fetch, tmp_path, wait_timeout=4.0)

    message = excinfo.value.message
    assert "not healthy" in message and "removed" in message
    assert not (traefik / routermirror.STATIC_FILENAME).exists()
    assert not (traefik / routermirror.DYNAMIC_RELPATH).exists()
    cmds = runner.cmds()
    assert cmds.count(["docker", "restart", "ddev-router"]) == 2
    start_idx = cmds.index(["ddev", "start"])
    assert runner.calls[start_idx]["cwd"] == tmp_path / "inst"
    # order: restart, polls..., ddev start, restart
    assert cmds.index(["docker", "restart", "ddev-router"]) < start_idx
    assert cmds[-1] == ["docker", "restart", "ddev-router"]


def test_converge_failure_when_entrypoints_still_mismatch(tmp_path):
    traefik = tmp_path / "traefik"
    registry = _registry(tmp_path)
    runner = ScriptedRunner()
    fetch = SequencedFetch(["http-80"])  # never grows the mirror entrypoint

    with pytest.raises(RouterMirrorError, match="still differ"):
        _converge(registry, traefik, runner, fetch, tmp_path)

    assert not (traefik / routermirror.STATIC_FILENAME).exists()
    assert ["ddev", "start"] in runner.cmds()
    assert runner.cmds().count(["docker", "restart", "ddev-router"]) == 2


def test_converge_failure_when_docker_restart_fails(tmp_path):
    runner = ScriptedRunner(fail={"docker restart"})
    with pytest.raises(RouterMirrorError, match="docker restart ddev-router failed"):
        _converge(
            _registry(tmp_path),
            tmp_path / "t",
            runner,
            SequencedFetch(["http-80"]),
            tmp_path,
        )
    assert ["ddev", "start"] in runner.cmds()


def test_converge_self_repair_problems_are_reported_in_the_error(tmp_path):
    runner = ScriptedRunner(health=["unhealthy"], fail={"ddev start"})
    with pytest.raises(RouterMirrorError) as excinfo:
        _converge(
            _registry(tmp_path),
            tmp_path / "t",
            runner,
            SequencedFetch(["http-80"]),
            tmp_path,
            wait_timeout=2.0,
        )
    assert "Self-repair problems" in excinfo.value.message
    assert "`ddev start` exited 1" in excinfo.value.message


def test_router_mirror_error_is_a_fleet_error():
    assert issubclass(RouterMirrorError, FleetError)


