def _fail_once(tmp_path, traefik, registry):
    routermirror.sync(registry, traefik_dir=traefik)
    with pytest.raises(RouterMirrorError):
        _converge(
            registry,
            traefik,
            ScriptedRunner(health=["unhealthy"]),
            SequencedFetch(["http-80"]),
            tmp_path,
            sync_first=False,
            wait_timeout=2.0,
        )


def test_failed_apply_writes_marker_and_blocks_sync_and_converge(tmp_path):
    registry, traefik = _wanted_9108(tmp_path)

    _fail_once(tmp_path, traefik, registry)

    marker = traefik / routermirror.FAILED_MARKER
    assert marker.read_text(encoding="utf-8").strip() == "9108"
    assert not (traefik / routermirror.STATIC_FILENAME).exists()

    result = routermirror.sync(registry, traefik_dir=traefik)
    assert result.changed is False
    assert result.mirrored == []
    assert any(
        routermirror.FAILED_MARKER in r and "fleet refresh-ports" in r for r in result.skipped
    )
    assert not (traefik / routermirror.STATIC_FILENAME).exists()

    runner = ScriptedRunner()
    message, _ = _converge(
        registry, traefik, runner, SequencedFetch(["http-80"]), tmp_path, sync_first=False
    )
    assert "failed apply" in message
    assert runner.calls == []


