def test_oserror_from_ddev_start_during_repair_still_raises_router_mirror_error(tmp_path):
    registry, traefik = _wanted_9108(tmp_path)

    class Boom(ScriptedRunner):
        def __call__(self, cmd, **kwargs):
            if cmd[:2] == ["ddev", "start"]:
                raise OSError("ddev vanished")
            return super().__call__(cmd, **kwargs)

    runner = Boom(health=["unhealthy"])
    with pytest.raises(RouterMirrorError) as excinfo:
        _converge(
            registry, traefik, runner, SequencedFetch(["http-80"]), tmp_path, wait_timeout=2.0
        )

    assert "ddev vanished" in excinfo.value.message
    assert runner.cmds()[-1] == ["docker", "restart", "ddev-router"]  # second restart still ran


def test_exceptions_from_the_second_restart_are_reported(tmp_path):
    registry, traefik = _wanted_9108(tmp_path)
    restarts = []

    class Boom(ScriptedRunner):
        def __call__(self, cmd, **kwargs):
            if cmd[:2] == ["docker", "restart"]:
                restarts.append(1)
                if len(restarts) == 2:
                    raise RuntimeError("daemon gone")
            return super().__call__(cmd, **kwargs)

    with pytest.raises(RouterMirrorError, match="second `docker restart ddev-router` failed"):
        _converge(
            registry,
            traefik,
            Boom(health=["unhealthy"]),
            SequencedFetch(["http-80"]),
            tmp_path,
            wait_timeout=2.0,
        )


def test_health_check_exception_counts_as_unhealthy(tmp_path):
    registry, traefik = _wanted_9108(tmp_path)

    class Boom(ScriptedRunner):
        def __call__(self, cmd, **kwargs):
            if cmd[:2] == ["docker", "inspect"]:
                raise ValueError("garbled")
            return super().__call__(cmd, **kwargs)

    with pytest.raises(RouterMirrorError, match="not healthy"):
        _converge(
            registry, traefik, Boom(), SequencedFetch(["http-80"]), tmp_path, wait_timeout=2.0
        )


def test_health_check_uses_timeout_fallback_template_and_accepts_running(tmp_path):
    registry, traefik = _wanted_9108(tmp_path)
    runner = ScriptedRunner(health=["running"])
    fetch = SequencedFetch(["http-80"], ["http-80", "fleet-mirror-9108"])

    message, _ = _converge(registry, traefik, runner, fetch, tmp_path)

    assert message.startswith("restarted ddev-router")
    inspect = next(c for c in runner.calls if c["cmd"][:2] == ["docker", "inspect"])
    assert inspect["timeout"] == 10.0
    assert "{{if .State.Health}}" in inspect["cmd"][3] and ".State.Status" in inspect["cmd"][3]


