    traefik.mkdir()
    (traefik / "static_config.fleet-spike.yaml").write_text(
        'entryPoints:\n  fleet-mirror-9108:\n    address: ":9108"\n', encoding="utf-8"
    )
    registry = _registry(tmp_path)

    profiles, skipped = routermirror.mirror_profiles(registry, traefik_dir=traefik)
    assert profiles == []
    assert len(skipped) == 1
    assert "static_config.fleet-spike.yaml" in skipped[0] and "9108" in skipped[0]

    result = routermirror.sync(registry, traefik_dir=traefik)
