def test_converge_lock_held_skips_without_restart(tmp_path):
    import fcntl

    registry, traefik = _wanted_9108(tmp_path)
    routermirror.sync(registry, traefik_dir=traefik)
    lock = tmp_path / "locks" / routermirror.LOCK_NAME
    lock.parent.mkdir()
    holder = open(lock, "a+")
    fcntl.flock(holder.fileno(), fcntl.LOCK_EX)
    runner = ScriptedRunner()
    sleeps = []
    clock = iter(range(0, 1000))
    try:
        message = routermirror.converge(
            registry,
            instance_dir=tmp_path / "inst",
            traefik_dir=traefik,
            runner=runner,
            fetch=SequencedFetch(["http-80"]),
            lock_path=lock,
            lock_wait=3.0,
            sleep=sleeps.append,
            monotonic=lambda: float(next(clock)),
        )
    finally:
        holder.close()

    assert message == "another deploy holds the router-mirror lock; skipped"
    assert runner.calls == []
    assert sleeps  # it polled


def test_sync_lock_held_writes_nothing(tmp_path):
    import fcntl

    registry, traefik = _wanted_9108(tmp_path)
    lock = tmp_path / "locks" / routermirror.LOCK_NAME
    lock.parent.mkdir()
    holder = open(lock, "a+")
    fcntl.flock(holder.fileno(), fcntl.LOCK_EX)
    clock = iter(range(0, 1000))
    try:
        result = routermirror.sync(
            registry,
            traefik_dir=traefik,
            lock_path=lock,
            lock_wait=2.0,
            sleep=lambda s: None,
            monotonic=lambda: float(next(clock)),
        )
    finally:
        holder.close()

    assert result.changed is False
    assert any("lock" in r for r in result.skipped)
    assert not (traefik / routermirror.STATIC_FILENAME).exists()


def test_lock_is_taken_released_and_created(tmp_path):
    registry, traefik = _wanted_9108(tmp_path)
    lock = routermirror.lock_path_for(tmp_path / "newdir" / "locks")

    assert routermirror.sync(registry, traefik_dir=traefik, lock_path=lock).changed is True
    assert lock.exists()
    # released: a second acquisition does not wait
    assert (
        routermirror.sync(registry, traefik_dir=traefik, lock_path=lock, lock_wait=0.0).changed
        is False
    )


